if 'parsed_date' not in globals():
    raise AssertionError('Step 2: parsed_date variable not found')

from datetime import datetime
parsed = globals()['parsed_date']

# Check type
if not isinstance(parsed, datetime):
    raise AssertionError('Step 2: parsed_date should be a datetime object')

# Check values (23/11/2026)
if parsed.year != 2026:
    raise AssertionError(f'Step 2: Year should be 2026, got {parsed.year}')
if parsed.month != 11:
    raise AssertionError(f'Step 2: Month should be 11, got {parsed.month}')
if parsed.day != 23:
    raise AssertionError(f'Step 2: Day should be 23, got {parsed.day}')

# Check day was printed
if '23' not in output:
    raise AssertionError('Step 2: Should print the day (23)')

print('TEST_PASSED')
